import{z as o,x as i,o as t,c as d,q as r,j as n,D as A,d as a,s,S as l,b as e}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"Meta 分析","description":"","frontmatter":{"title":"Meta 分析","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/pe-meta-analysis.md","filePath":"econ/pe-meta-analysis.md","lastUpdated":1791413859000}'),m={name:"econ/pe-meta-analysis.md"};function p(C,E,u,F,D,c){const B=i("Mermaid");return t(),d("div",null,[E[2]||(E[2]=r('<h1 id="meta-分析" tabindex="-1">Meta 分析 <a class="header-anchor" href="#meta-分析" aria-label="Permalink to &quot;Meta 分析&quot;">​</a></h1><div class="epigraph"><p>文献的平均效应不是参数，是统计量：它被发表过程筛过、被点位挑过；meta 分析的工作是把筛子翻过来看。</p><footer>—— Glass 1976；Egger 等, BMJ 1997；Card, Kluve and Weber, JEP 2018</footer></div><p><a href="/econ/pe-external-validity">上一课</a>把外推的断点拆开，留下一个尾巴：多点复制之后，证据怎么合成？本课写 meta 分析——Glass 1976 把「对分析的分析」命名成方法，把外部有效性从叙述变成估计。它是本课程综合单元的技术核心，也是<a href="/econ/multiple-testing-econ">多重检验</a>与点位选择两道筛子的收口处。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>把一批研究的效应量平均起来，要同时回答三个问题，每个都有坑。<strong>平均多少</strong>：固定效应假设所有研究挤在一个真值上，几乎从不成立——研究来自不同人群、点位与实施质量；随机效应把研究间方差 \\(\\tau^2\\) 显式建模，权重从「只按精度」改成「精度加分布」，异质性大时固定效应的窄置信区间是假的。<strong>异质性多大</strong>：\\(\\tau^2\\) 与 \\(I^2\\) 是要报告的主结果，不是脚注——分布的宽度才是外推的可用信息（上一课的口径）。<strong>合成本身干净吗</strong>：不干净。发表过程偏好小样本显著结果，漏斗图于是不对称；点位选择与规格搜索各筛一道；同一个研究里抽出的几十个估计高度相关，当独立观测平均，方差被假性缩小几十倍。合成不修复质量，只放大它——垃圾进，分布更宽的垃圾出。</p><p><span class="marginnote">数字实例：\\(I^2\\) 读作「离散中研究间真差异占的比例」。若 30 个研究算出 \\(I^2=75\\%\\)，意味着四分之三的离散来自「这些研究本来就在测不同的东西」，只有四分之一是抽样噪声——此时把研究挤成一个大数没有意义，分布的宽度本身才是答案。</span></p><p><span class="marginnote">Doucouliagos 与 Stanley 对几十年最低工资研究的元回归是最直白的示范：精选研究的弹性集中在小负值，校正发表选择后中位数趋近零——表观共识可以是筛子的形状。这与<a href="/econ/minimum-wage-debates">最低工资：两代文献</a>里「对照构造之争」是同一现象的两个层次。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>工序五步。第一，定协议：纳入标准、结局、时段预先写死（医学的 PRISMA 传统），否则选择在检索阶段就发生。第二，抽效应量：标准化口径统一（均值差、弹性、对数几率），同一研究的多个估计按研究聚类，不进独立平均。第三，估合成：逆方差加权的随机效应模型，\\(\\tau^2\\) 用矩估计（DerSimonian–Laird）或其修订；异质性连同合成值一起报。第四，查筛子：漏斗图不对称性（Egger 检验）、PET/FAT 元回归（Stanley–Doucouliagos）把发表选择的斜率显式估出来；精确研究贴近真值、模糊研究被推离，形状本身就是证据。第五，解释异质性：元回归把调节变量放进模型——Card、Kluve 与 Weber 对主动劳动市场政策的元分析是范式：项目类型、目标群体、周期状态比国别更能解释 \\(\\tau^2\\)，设计特征可携带，国别口号不可携带。</p>',9)),(t(),n(l,null,{default:A(()=>[s(B,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20PROTO%5B%22%E5%8D%8F%E8%AE%AE%3A%20%E7%BA%B3%E5%85%A5%E6%A0%87%E5%87%86%E9%A2%84%E6%B3%A8%E5%86%8C%22%5D%20--%3E%20EX%5B%22%E6%8A%BD%E5%8F%96%E6%95%88%E5%BA%94%E9%87%8F%2C%20%E6%8C%89%E7%A0%94%E7%A9%B6%E8%81%9A%E7%B1%BB%22%5D%0A%20%20EX%20--%3E%20RE%5B%22%E9%9A%8F%E6%9C%BA%E6%95%88%E5%BA%94%E5%90%88%E6%88%90%E4%B8%8E%20tau%20%E6%96%B9%22%5D%0A%20%20RE%20--%3E%20FUN%7B%22%E6%BC%8F%E6%96%97%E5%9B%BE%E5%AF%B9%E7%A7%B0%3F%22%7D%0A%20%20FUN%20--%3E%7C%E5%90%A6%7C%20PET%5B%22PET%2FFAT%20%E6%A0%A1%E6%AD%A3%E5%8F%91%E8%A1%A8%E9%80%89%E6%8B%A9%22%5D%0A%20%20FUN%20--%3E%7C%E6%98%AF%7C%20MOD%5B%22%E5%85%83%E5%9B%9E%E5%BD%92%E8%A7%A3%E9%87%8A%E5%BC%82%E8%B4%A8%E6%80%A7%22%5D%0A%20%20PET%20--%3E%20MOD%0A%20%20MOD%20--%3E%20OUT%5B%22%E5%88%86%E5%B8%83%E4%B8%8E%E8%B0%83%E8%8A%82%E5%8F%98%E9%87%8F%2C%20%E9%9D%9E%E5%8D%95%E4%B8%80%E5%9D%87%E5%80%BC%22%5D%0A"})]),fallback:A(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[a("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,[a("机制是把「研究的抽样」显式建模：观测到的效应量 = 真值 + 研究层抽样噪声 + 研究间方差，第三项是随机效应对固定效应的全部增量。"),e("span",{class:"marginnote"},"直觉类比：漏斗图像一张靶纸——枪法准的射手（大样本研究）弹孔集中在靶心，枪法散的（小样本）弹孔均匀散在四周，整体该呈对称漏斗。若纸上只见「离靶心远的弹孔」而不见同距离偏另一侧的，就是有人把打偏的成绩撕掉了：缺角本身就是筛子的指纹。"),a("发表偏倚在机制上是对「哪些研究可被观测」的截断——meta 的推断对象因此是"),e("strong",null,"可观测文献的分布"),a("，校正方法是在这个分布上反解筛选规则。不这么做会错在哪：投票计数（数显著结果的个数）把筛子隐形化；「综述叙事」把权重交给作者直觉；给研究质量加权的合成若不给权重规则，只是另一种叙事。")],-1)),(t(),n(l,null,{default:A(()=>[s(B,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20ALL%5B%22%E5%85%A8%E9%83%A8%E7%A0%94%E7%A9%B6%3A%20%E7%9C%9F%E5%80%BC%E9%99%84%E8%BF%91%2C%20%E7%B2%BE%E5%BA%A6%E4%B8%8D%E5%90%8C%22%5D%20--%3E%20BIG%5B%22%E5%A4%A7%E6%A0%B7%E6%9C%AC%3A%20%E4%BC%B0%E8%AE%A1%E8%B4%B4%E8%BF%91%E7%9C%9F%E5%80%BC%22%5D%0A%20%20ALL%20--%3E%20SMALL%5B%22%E5%B0%8F%E6%A0%B7%E6%9C%AC%3A%20%E4%BC%B0%E8%AE%A1%E6%95%A3%E5%B8%83%E5%AE%BD%22%5D%0A%20%20BIG%20--%3E%20CENTER%5B%22%E8%81%9A%E5%9C%A8%E6%BC%8F%E6%96%97%E5%8F%A3%22%5D%0A%20%20SMALL%20--%3E%20PUB%7B%22%E7%BC%96%E8%BE%91%E4%B8%8E%E5%AE%A1%E7%A8%BF%E5%8F%AA%E5%8F%91%E6%98%BE%E8%91%97%E7%9A%84%3F%22%7D%0A%20%20PUB%20--%20%22%E6%98%AF%22%20--%3E%20KEEP%5B%22%E5%8F%AA%E6%9C%89%E8%BF%9C%E7%A6%BB%E9%9B%B6%E7%9A%84%E5%B0%8F%E6%A0%B7%E6%9C%AC%E8%A2%AB%E5%8F%91%E8%A1%A8%22%5D%0A%20%20PUB%20--%20%22%E5%90%A6%22%20--%3E%20SYM%5B%22%E6%BC%8F%E6%96%97%E4%BF%9D%E6%8C%81%E5%AF%B9%E7%A7%B0%22%5D%0A%20%20KEEP%20--%3E%20SKEW%5B%22%E6%96%87%E7%8C%AE%E5%88%86%E5%B8%83%E8%A2%AB%E6%8B%89%E7%A6%BB%E7%9C%9F%E5%80%BC%2C%20%E6%BC%8F%E6%96%97%E7%BC%BA%E8%A7%92%22%5D%0A"})]),fallback:A(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=r('<p>上图回答的问题是五步工序里「查筛子」一步的原理：工序图画 meta 怎么做，这张画发表截断怎么把漏斗掰弯——观测到的分布是「真值分布过筛后的条件分布」，Egger 检验与 PET/FAT 反解的正是这条筛选规则。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>meta 不能凭空修复识别：被合成研究的内生效障各不相同，合成放大它们而不是抵消。<span class="marginnote">常见误区：初学者以为「多研究平均能抵消各自的偏误」。平均抵消的是<strong>随机</strong>噪声；若各研究都因同类原因向同一方向偏（都用同一套有漏的对照），平均后偏误原样保留，只是披上了「30 项研究共识」的外衣，反而更难被质疑。</span>LATE 与依从边际跨研究不同（依从课的口径），直接平均不同工具的 LATE 是在平均不同参数。异质性的元回归受生态谬误与调节变量间的共线限制，解释要克制。协议化也止于检索与纳入——代码与分析层面的选择仍要靠复现包与数据透明兜底。</p><p>后课默认：证据综合的产出是分布与调节结构，不是一个大数；下一课把全部工具放回真实政策案例收束。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>随机效应是默认：研究间方差 \\(\\tau^2\\) 与 \\(I^2\\) 是主结果。</li><li>发表与点位是两种筛子；漏斗不对称与 PET/FAT 把筛子显式化。</li><li>同研究多估计按研究聚类，不当独立观测。</li><li>异质性解释靠设计特征的元回归，国别口号不算解释。</li><li>出处：Glass 1976；DerSimonian and Laird 1986；Egger 等, <em>BMJ</em> 1997；Stanley and Doucouliagos；Card, Kluve and Weber, <em>JEP</em> 2018。</li></ul>',6))])}const h=o(m,[["render",p]]);export{T as __pageData,h as default};
